    'name': ['full_name', 'name', 'userName'],
    'email': ['email', 'email_address'],
    'created_date': ['registration_date', 'created_at', 'joined'],
    'status': ['status', 'is_active', 'active'],
}
fields = ['user_id', 'name', 'email', 'created_date', 'status']

def clean_status(v):
    if v is None or pd.isna(v) or str(v).strip() == '':
        return None
    s = str(v).strip().lower()
    if s in ('true', '1', 'yes', 'active'):
        return 'active'
    if s in ('false', '0', 'no', 'inactive'):
        return 'inactive'
    return str(v)

def load(path):
    if path.endswith('.json'):
        with open(path, encoding='utf-8') as f:
            obj = json.load(f)
        if isinstance(obj, dict):
            obj = obj.get('users', obj.get('data', obj.get('records', obj)))
        df = pd.DataFrame(obj)
    elif path.endswith('.csv'):
        df = pd.read_csv(path, dtype=object, keep_default_na=False)
    else:
        df = pd.read_parquet(path)
    rows = []
    for _, row in df.iterrows():
        rec = {}
        for field, names in aliases.items():
            rec[field] = None
            for name in names:
                if name in df.columns and pd.notna(row[name]) and str(row[name]).strip() != '':
                    rec[field] = row[name]
                    break
        if rec['user_id'] is None:
            continue
        rec['user_id'] = int(float(rec['user_id']))
        if rec['created_date'] is not None:
            d = pd.to_datetime(rec['created_date'], errors='coerce')
            rec['created_date'] = d.strftime('%Y-%m-%d') if not pd.isna(d) else str(rec['created_date'])[:10]
        rec['status'] = clean_status(rec['status'])
        for f in ('name', 'email'):
            if rec[f] is not None:
                rec[f] = str(rec[f])
        rows.append(rec)
    return rows

by_id = {}
for source, path in sources:
    for rec in load(path):
        by_id.setdefault(rec['user_id'], {})[source] = rec

priority = ['source_a', 'source_b', 'source_c']
merged, conflicts = [], []
for uid in sorted(by_id):
    records = by_id[uid]
    result = {'user_id': uid}
    for field in fields[1:]:
        vals = {s: records[s].get(field) for s in priority if s in records and records[s].get(field) is not None}
        distinct = list(dict.fromkeys(vals.values()))
        if len(distinct) > 1:
            selected = next(vals[s] for s in priority if s in vals)
            conflicts.append({'user_id': uid, 'field': field, 'values': vals, 'selected': selected})
        result[field] = next((records[s].get(field) for s in priority if s in records and records[s].get(field) is not None), None)
    merged.append(result)

out = pd.DataFrame(merged, columns=fields)
out['user_id'] = out['user_id'].astype('int64')
for f in fields[1:]:
    out[f] = out[f].astype('string')
out.to_parquet('/app/merged_users.parquet', index=False)
with open('/app/conflicts.json', 'w', encoding='utf-8') as f:
    json.dump({'total_conflicts': len(conflicts), 'conflicts': conflicts}, f, indent=2, ensure_ascii=False)
print('merged rows:', len(out))
print('conflicts:', len(conflicts))
print(out.to_string(index=False))
